24	
25	/**
26	 * Case read, follow-up merge, and the two operational endpoints backup and
27	 * restore need.
28	 *
29	 * <p>The follow-up body is taken as a raw {@link JsonNode} rather than a typed
30	 * DTO on purpose. The follow-up shape is produced by an AI extraction pipeline
31	 * and is not fully known at build time; binding it to a fixed class would turn
32	 * every unanticipated key into a framework-level 400 with an unhelpful message.
33	 * Routing it through {@link CasePayloadNormalizer} instead gives control over
34	 * exactly what is tolerated and produces errors that name the offending path.
35	 */
36	@RestController
37	@RequestMapping("/cases")
38	public class CaseController {
39	
40	    private static final Logger log = LoggerFactory.getLogger(CaseController.class);
41	
42	    private final CaseRepository repository;
43	    private final MergeService mergeService;
44	    private final CaseSnapshotValidator snapshotValidator;
45	
46	    public CaseController(
47	            CaseRepository repository,
48	            MergeService mergeService,
49	            CaseSnapshotValidator snapshotValidator) {
50	        this.repository = repository;
51	        this.mergeService = mergeService;
52	        this.snapshotValidator = snapshotValidator;
53	    }
54	
55	    /** Most recent version of a case. 404 when unknown. */
56	    @GetMapping("/{caseId}")
57	    public CaseView getCase(@PathVariable String caseId) {
58	        return repository.requireLatest(caseId);
59	    }
60	
61	    /**
62	     * Every known case, in summary.
63	     *
64	     * <p>Not in the brief's endpoint list, but {@code ops/backup.sh} is required
65	     * to "fetch all known cases", which is impossible when the only read path
66	     * needs an id you already have to know. Summaries rather than full cases so
67	     * the response stays small as case count grows; the backup script pages
68	     * through and fetches each case in full.
69	     */
70	    @GetMapping
71	    public Map<String, Object> listCases() {
72	        List<CaseView.Summary> cases = repository.listSummaries();
73	        return Map.of("count", cases.size(), "cases", cases);
74	    }
75	
76	    /**
77	     * Merges a follow-up onto the stored case and returns the annotated result.
78	     *
79	     * <p>The merge runs inside the repository's atomic append, so validation
80	     * failures leave storage untouched and two concurrent follow-ups cannot diff
81	     * against the same predecessor.
82	     */
83	    @PostMapping("/{caseId}/follow-ups")
84	    public CaseView submitFollowUp(@PathVariable String caseId, @RequestBody JsonNode body) {
85	        NormalizedCasePayload payload = mergeService.normalizer().normalize(body, false);
86	        requireMatchingCaseId(caseId, payload.caseId());
87	
88	        // Fail fast on an unknown case before doing any merge work.
89	        if (!repository.exists(caseId)) {
90	            throw new ai.theragenx.pvcase.web.error.CaseNotFoundException(caseId);
91	        }
92	
93	        CaseView merged = repository.appendVersion(
94	                caseId, previous -> mergeService.merge(previous, payload));
95	
96	        log.info("Merged follow-up onto {} -> v{} ({})",
97	                caseId, merged.version(), merged.changeSummary());
98	        return merged;
99	    }
100	
101	    /**
102	     * Replaces a case with a snapshot from a backup file.
103	     *
104	     * <p>Also not in the brief. {@code ops/restore.sh} has to put cases back, and
105	     * routing a restore through the follow-up endpoint would be wrong twice over:
106	     * it would bump versions on every run instead of being idempotent, and it
107	     * cannot recreate a case that is missing entirely, which is the situation a
108	     * restore exists for.
109	     *
110	     * <p>PUT rather than POST because the semantics really are "make the case be
111	     * exactly this". That is what makes running the same backup file through
112	     * twice a no-op rather than a second stacked version.
113	     */
114	    @PutMapping("/{caseId}")
115	    public ResponseEntity<CaseView> restoreCase(
116	            @PathVariable String caseId, @RequestBody CaseView snapshot) {
117	
118	        requireMatchingCaseId(caseId, snapshot == null ? null : snapshot.caseId());
119	        // Restore bypasses the follow-up normaliser entirely, so this is the only
120	        // thing standing between a hand-edited backup file and corrupt storage.
121	        snapshotValidator.validate(snapshot);
122	
123	        boolean existed = repository.exists(caseId);
124	        CaseView restored = repository.replace(
125	                new CaseView(
126	                        caseId,
127	                        snapshot.version(),
128	                        snapshot.comparedToVersion(),
129	                        snapshot.caseClassification(),
130	                        snapshot.extractedAt(),
131	                        snapshot.sourceDocument(),
132	                        snapshot.missingFields() == null ? List.of() : snapshot.missingFields(),
133	                        Map.of(),
134	                        snapshot.sections())
135	                        .withRecomputedSummary());
136	
137	        log.info("Restored case {} at v{} ({})",
138	                caseId, restored.version(), existed ? "replaced" : "created");
139	
140	        return existed
141	                ? ResponseEntity.ok(restored)
142	                : ResponseEntity.status(201).body(restored);
143	    }
144	
145	    /**
146	     * The URL is authoritative. A body id that disagrees is rejected rather than
147	     * silently preferred either way — restoring or merging into the wrong case is
148	     * exactly the kind of quiet data corruption that is expensive to find later.
149	     */
150	    private void requireMatchingCaseId(String pathCaseId, String bodyCaseId) {
151	        if (bodyCaseId != null && !bodyCaseId.equals(pathCaseId)) {
152	            throw new InvalidPayloadException("case_id", String.format(
153	                    "body declares '%s' but the URL targets '%s'", bodyCaseId, pathCaseId));
154	        }
155	    }
156	}

