1	package ai.theragenx.pvcase.store;
2	
3	import ai.theragenx.pvcase.domain.CaseView;
4	import ai.theragenx.pvcase.web.error.CaseNotFoundException;
5	import org.springframework.stereotype.Repository;
6	
7	import java.util.ArrayList;
8	import java.util.Comparator;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.Optional;
12	import java.util.concurrent.ConcurrentHashMap;
13	import java.util.function.UnaryOperator;
14	
15	/**
16	 * In-memory case storage, versioned.
17	 *
18	 * <p>The brief only requires "the most recent version", and only the most recent
19	 * version is exposed over HTTP. History is still kept internally for two
20	 * reasons: a diff is meaningless without a well-defined predecessor, and
21	 * retaining prior versions as immutable snapshots removes any chance of
22	 * accidentally mutating v1 while constructing v2. Full snapshots cost nothing
23	 * at this scale.
24	 *
25	 * <p>This is not an audit trail. Everything is lost on restart, which is what
26	 * {@code ops/backup.sh} exists to mitigate.
27	 */
28	@Repository
29	public class CaseRepository {
30	
31	    /** caseId -> immutable, append-only list of versions, oldest first. */
32	    private final Map<String, List<CaseView>> versionsByCase = new ConcurrentHashMap<>();
33	
34	    public Optional<CaseView> findLatest(String caseId) {
35	        List<CaseView> versions = versionsByCase.get(caseId);
36	        if (versions == null || versions.isEmpty()) {
37	            return Optional.empty();
38	        }
39	        return Optional.of(versions.get(versions.size() - 1));
40	    }
41	
42	    public CaseView requireLatest(String caseId) {
43	        return findLatest(caseId).orElseThrow(() -> new CaseNotFoundException(caseId));
44	    }
45	
46	    public boolean exists(String caseId) {
47	        return versionsByCase.containsKey(caseId);
48	    }
49	
50	    /** Latest version of every known case, ordered by id so backups diff cleanly. */
51	    public List<CaseView.Summary> listSummaries() {
52	        return versionsByCase.values().stream()
53	                .filter(versions -> !versions.isEmpty())
54	                .map(versions -> versions.get(versions.size() - 1))
55	                .map(CaseView::toSummary)
56	                .sorted(Comparator.comparing(CaseView.Summary::caseId))
57	                .toList();
58	    }
59	
60	    /** Seeds the initial version. Rejects a second seed rather than silently resetting. */
61	    public CaseView seed(CaseView initialVersion) {
62	        List<CaseView> existing = versionsByCase.putIfAbsent(
63	                initialVersion.caseId(), List.of(initialVersion));
64	        if (existing != null) {
65	            throw new IllegalStateException(
66	                    "case " + initialVersion.caseId() + " has already been seeded");
67	        }
68	        return initialVersion;
69	    }
70	
71	    /**
72	     * Applies {@code mergeFn} to the current latest version and appends the result
73	     * as a new version, atomically.
74	     *
75	     * <p>The whole read-merge-append runs inside {@link ConcurrentHashMap#compute},
76	     * so two concurrent follow-ups on the same case cannot both diff against the
77	     * same predecessor and lose one another's changes. If {@code mergeFn} throws —
78	     * which is how validation failures surface — the map entry is left untouched,
79	     * giving us "validate fully before mutating anything" for free.
80	     */
81	    public CaseView appendVersion(String caseId, UnaryOperator<CaseView> mergeFn) {
82	        List<CaseView> updated = versionsByCase.compute(caseId, (id, existing) -> {
83	            if (existing == null || existing.isEmpty()) {
84	                throw new CaseNotFoundException(id);
85	            }
86	            CaseView previous = existing.get(existing.size() - 1);
87	            CaseView merged = mergeFn.apply(previous);
88	
89	            List<CaseView> next = new ArrayList<>(existing);
90	            next.add(merged);
91	            return List.copyOf(next);
92	        });
93	        return updated.get(updated.size() - 1);
94	    }
95	
96	    /**
97	     * Restores a case to exactly the supplied snapshot, discarding local history.
98	     *
99	     * <p>Used only by {@code PUT /cases/{id}}. Replacing rather than appending is
100	     * what makes restore idempotent: running the same backup file through twice
101	     * leaves identical state, because the second run overwrites with the same
102	     * content instead of stacking another version on top.
103	     */
104	    public CaseView replace(CaseView snapshot) {
105	        versionsByCase.put(snapshot.caseId(), List.of(snapshot));
106	        return snapshot;
107	    }
108	}

