        restore(snapshot("\"version\": 0,", VALID_FIELD)).andExpect(status().isBadRequest());

        mockMvc.perform(get("/cases/{id}", "PV-REST-0001"))
                .andExpect(jsonPath("$.version", is(4)));
    }

