14	/**
15	 * Turns incoming case-shaped JSON into a {@link NormalizedCasePayload}.
16	 *
17	 * <p>This class exists to be the <em>only</em> place that copes with input
18	 * variation. Everything downstream — the merge engine, the store, the response —
19	 * works against one predictable structure. When the real follow-up fixture
20	 * arrives and turns out to differ, this is the single file that changes.
21	 *
22	 * <p>The tolerance here is bounded on purpose. It accepts variations that are
23	 * plausible from an AI extraction pipeline (snake_case vs camelCase keys, a bare
24	 * scalar where an envelope was expected, sections and fields nobody has seen
25	 * before) and rejects anything genuinely ambiguous. A field-depth object with no
26	 * {@code value} key is the clearest example: it could be a malformed envelope or
27	 * an intended sub-section, and guessing wrong would either lose data or invent
28	 * it. Refusing with a precise 400 is better than either.
29	 *
30	 * <p>All violations are collected before any is thrown, so a caller fixing a
31	 * payload sees every problem in one response.
32	 */
33	@Component
34	public class CasePayloadNormalizer {
35	
36	    private static final int MAX_VIOLATIONS_REPORTED = 25;
37	
38	    /** Closed set; see the violation message where this is used. */
39	    static final List<String> ALLOWED_CLASSIFICATIONS =
40	            List.of("significant", "non-significant");
41	
42	    /**
43	     * Top-level keys this service understands. Extra keys alongside them are
44	     * tolerated — an extraction pipeline may legitimately attach its own metadata,
45	     * and rejecting a payload for carrying a run id would be hostile. But a payload
46	     * containing *none* of these is not a follow-up at all.
47	     */
48	    private static final List<String> RECOGNISED_KEYS = List.of(
49	            "sections", "case_classification", "caseClassification",
50	            "missing_fields", "missingFields", "case_id", "caseId",
51	            "extracted_at", "extractedAt", "source_document", "sourceDocument");
52	
53	    private static boolean hasRecognisableContent(JsonNode root) {
54	        for (String key : RECOGNISED_KEYS) {
55	            if (root.has(key)) {
56	                return true;
57	            }
58	        }
59	        return false;
60	    }
61	
62	    private static final String NAME_RULE =
63	            "section and field names must be non-blank and must not contain '.', '/' "
64	                    + "or whitespace, because field paths are built as 'section.field'";
65	
66	    /**
67	     * Field paths are the flat key the UI sorts by and {@code /queries} refers to,
68	     * and they are built by joining a section and field name with a dot. A name
69	     * containing a dot therefore makes the path ambiguous: section {@code a} with
70	     * field {@code b.c} and section {@code a.b} with field {@code c} both produce
71	     * {@code a.b.c}, and a {@code missing_fields} entry naming that path would flag
72	     * both. Slashes and surrounding whitespace break the same way, since path
73	     * resolution normalises both.
74	     *
75	     * <p>Rejecting the name is better than escaping it. Escaping would make every
76	     * path in the API harder to read for a case of extraction output that has never
77	     * been seen, and a precise 400 tells the pipeline owner exactly what to change.
78	     */
79	    private static boolean isUsableName(String name) {
80	        if (name == null || name.isBlank()) {
81	            return false;
82	        }
83	        if (!name.equals(name.trim())) {
84	            return false;
85	        }
86	        for (int i = 0; i < name.length(); i++) {
87	            char c = name.charAt(i);
88	            if (c == '.' || c == '/' || Character.isWhitespace(c)) {
89	                return false;
90	            }
91	        }
92	        return true;
93	    }
94	
95	    /**
96	     * @param root the parsed request body
97	     * @param requireSections true for a bootstrap/restore payload, false for a
98	     *     follow-up — a follow-up that only changes the classification is legitimate
99	     */
