101	        List<FieldViolation> violations = new ArrayList<>();
102	
103	        if (root == null || !root.isObject()) {
104	            throw new InvalidPayloadException("$", "Request body must be a JSON object");
105	        }
106	
107	        String caseId = readText(root, violations, "case_id", "caseId");
108	        String extractedAt = readText(root, violations, "extracted_at", "extractedAt");
109	        String sourceDocument = readText(root, violations, "source_document", "sourceDocument");
110	
111	        JsonNode classificationNode = firstPresent(root, "case_classification", "caseClassification");
112	        boolean classificationPresent = classificationNode != null;
113	        String caseClassification = null;
114	        if (classificationPresent && !classificationNode.isNull()) {
115	            if (!classificationNode.isTextual()) {
116	                violations.add(new FieldViolation(
